//Bit   5:2-       0   - reserved
//Bit 1    -       0   - n205_i_dbg_stop
//Bit 0    -       0   - n205_pc_enable
#define AOCPU_CPU_CTRL2                            ((0x0002  << 2) + 0xfe09c000)
